  restoreExistingTickets(repo, recorded);
  if (prePmStatus) {
    const postPmStatus = getWorkingTreeChanges(repo);
    for (const f of postPmStatus) {
      if (!prePmStatus.has(f)) {
        try {
          git(repo, 'reset', 'HEAD', '--', f);
        } catch {}
        try {
          git(repo, 'checkout', 'HEAD', '--', f);
